distributionManifestText:
{
  "package": "oats.okf",
  "version": "5.3.0",
  "description": "Official OATS knowledge operations on Open Knowledge Format bases: the working-soul knowledge slot (consultation and instance knowledge), the knowledge harvester and maintainer capabilities and package souls, and the harvest-review trigger template.",
  "compatibility": {
    "oats": ">=0.49.0"
  },
  "capabilities": [
    "capabilities/oats-okf",
    "capabilities/oats-okf-harvest",
    "capabilities/oats-okf-maintenance"
  ],
  "souls": [
    "souls/knowledge-harvester",
    "souls/knowledge-maintainer"
  ],
  "triggers": [
    { "id": "harvest-review", "file": "triggers/harvest-review.json" }
  ]
}

distributionFiles.text:
{
  "parameters": {
    "repo": { "path": "on.repo", "required": true, "description": "the knowledge-base repository, github.com/<owner>/<repo>" },
    "base": { "path": "on.base", "default": "main", "description": "the knowledge base's accepted branch" },
    "harness": { "path": "spawn.harness", "default": "claude", "description": "the maintainer's harness: pi, claude or codex" },
    "model": { "path": "spawn.model", "default": "opus", "description": "the maintainer's model" }
  },
  "definition": {
    "id": "okf-harvest-review",
    "enabled": true,
    "kind": "trigger",
    "on": {
      "source": "github.pull_request",
      "events": ["opened", "reopened", "ready_for_review"],
      "labels": ["okf-harvest"],
      "poll": "2m"
    },
    "spawn": {
      "soul": "oats.okf/knowledge-maintainer",
      "purpose": "review-pr-{number}",
      "task": "Review knowledge-base PR {repo}#{number} ({url}). Load the knowledge-review skill first."
    },
    "concurrency": { "max": 2, "perKey": 1 }
  }
}
